package com.sunrise.dentalclinic.controller;
import com.sunrise.dentalclinic.service.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/bills")public class BillingController{private final BillingService service;private final AppointmentService appointments;public BillingController(BillingService s,AppointmentService a){service=s;appointments=a;}@GetMapping("/new")String form(@RequestParam(required=false)Long appointmentId,@RequestParam(required=false)String appointmentNumber,Model m){if(appointmentId==null&&appointmentNumber!=null&&!appointmentNumber.isBlank())appointmentId=appointments.byNumber(appointmentNumber).getId();m.addAttribute("appointments",appointments.all());m.addAttribute("selectedAppointmentId",appointmentId);if(appointmentId!=null)m.addAttribute("preview",service.preview(appointmentId));return "bills/form";}@PostMapping String generate(@RequestParam Long appointmentId){return "redirect:/bills/"+service.generate(appointmentId).getId();}@GetMapping("/{id}")String receipt(@PathVariable Long id,Model m){m.addAttribute("bill",service.get(id));return "bills/receipt";}}
